#cookieBanner.cbShort { background-color: rgba(15, 15, 15, 0.95); border-radius: 5px; padding: 1em; width: 90%; position: fixed; bottom: 0px; margin: 5px auto; color: rgb(198, 198, 198); z-index: 100; text-align: center; left: 50%; transform: translate(-50%, 0px); font-size: 14px; }
