.backToscrollableContent .ph-icon-chevron-left { position: relative; margin-right: 10px; margin-left: 10px; font-size: 0.7em; pointer-events: none; }
.customizeMainContent { display: flex; justify-content: space-between; flex-wrap: wrap; align-items: center; }
.customizeMainContent .column { width: 100%; }
.customizeMainContent .title { font-size: 16px; font-weight: bold; color: rgb(255, 255, 255); cursor: pointer; }
.customizeMainContent p { margin-top: 12px; margin-bottom: 40px; width: 100%; }
.customizeMainContent span { color: rgb(255, 255, 255); }
.customizeToggleSwitch { position: relative; display: inline-block; width: 46px; height: 28px; }
.customizeToggleSwitch input { opacity: 0; width: 0px; height: 0px; }
.customizeToggleSwitch .slider { position: absolute; cursor: pointer; inset: 0px; background-color: rgb(198, 198, 198); transition: 0.4s; }
.customizeToggleSwitch .slider::before { position: absolute; content: ""; height: 24px; width: 24px; left: 3px; bottom: 2px; background-color: rgb(255, 255, 255); transition: 0.4s; }
.customizeToggleSwitch input:checked + .slider { background-color: rgb(255, 144, 0); }
.customizeToggleSwitch input:focus + .slider { box-shadow: rgb(255, 144, 0) 0px 0px 1px; }
.customizeToggleSwitch input:checked + .slider::before { transform: translateX(16px); }
.customizeToggleSwitch .slider.round { border-radius: 34px; }
.customizeToggleSwitch .slider.round::before { border-radius: 50%; }
.customizeToggleSwitch span { position: absolute; display: flex; flex-direction: column; justify-content: center; }
.customizeToggleSwitch span::before, .customizeToggleSwitch span::after { position: absolute; content: ""; width: 17px; height: 2px; top: 13px; left: 6px; background: rgb(198, 198, 198); transition: left 0.5s; }
.customizeToggleSwitch span::before { transform: rotate(45deg); }
.customizeToggleSwitch span::after { transform: rotate(-45deg); }
.customizeToggleSwitch input[type="checkbox"]:checked ~ div span { transform: translateX(16px); }
.customizeToggleSwitch input[type="checkbox"]:checked ~ div span::before { content: ""; background-color: transparent; position: relative; top: 4px; left: 11px; width: 6px; height: 15px; border-bottom: 2px solid rgb(255, 144, 0); border-right: 2px solid rgb(255, 144, 0); transform: rotate(45deg); }
.customizeToggleSwitch input[type="checkbox"]:checked ~ div.mobileBtn span::before { width: 7px; height: 16px; }
.customizeToggleSwitch input[type="checkbox"]:checked ~ div span::after { content: ""; background-color: transparent; }
